(function(){
  "use strict";

  // ============================================================
  // Constants & helpers
  // ============================================================
  var ORDINALS = ['الأولى','الثانية','الثالثة','الرابعة','الخامسة','السادسة','السابعة','الثامنة'];
  var DEFAULT_SCHEDULE = [
    ['07:00','07:40'], ['07:40','08:20'], ['08:20','09:00'], ['09:00','09:40'],
    ['09:40','10:20'], ['10:20','11:00'], ['11:00','11:40'], ['11:40','12:20'],
  ];
  var SCHED_KEY = 'report21-schedule-v1';
  var NAVY = '15445A', TEAL = '0DA9A6', TEAL_DEEP = '15445A', TEAL2 = '218CAA', TEAL_TINT = 'E3F5F4', GREEN = '07A869', GRAY = '5B6873', PURPLE = '7258A4', PURPLE_DEEP = '351375', ALERT = '7258A4', WHITE = 'FFFFFF';
  var CONTENT_WIDTH = 9906;
  var FONT = 'Tajawal';

  // ---- the two report designs (Word + PDF share the same palette) ----
  var DESIGNS = {
    official: { name:'التصميم الرسمي',
      main:'0DA9A6', deep:'15445A', names:'15445A', evid:'218CAA', tint:'E3F5F4',
      statFill:'0DA9A6', statColor:'FFFFFF', lesson:'0DA9A6', lessonSize:18, titleSize:20, lhSize:12,
      pieA:'#07A869', pieB:'#C1B489', pieTitle:'#15445A', evidLabel:'شواهد الحصة',
      margins:{top:560,bottom:560,left:620,right:620}, logoW:60, logoH:42 },
    blue: { name:'الأزرق والبنفسجي',
      main:'2E5FA3', deep:'1F3864', names:'1F3864', evid:'6A2C91', tint:'F2F2F2',
      statFill:'D9D9D9', statColor:'000000', lesson:'C0392B', lessonSize:24, titleSize:24, lhSize:16,
      pieA:'#2E5FA3', pieB:'#E97B30', pieTitle:'#1F3864', evidLabel:'الشواهد',
      margins:{top:900,bottom:900,left:1000,right:1000}, logoW:89, logoH:62 },
  };
  var DESIGN = DESIGNS.official;
  function applyDesign(key){
    DESIGN = DESIGNS[key] || DESIGNS.official;
    TEAL = DESIGN.main; TEAL_DEEP = DESIGN.deep; NAVY = DESIGN.names; TEAL2 = DESIGN.evid; TEAL_TINT = DESIGN.tint;
    return DESIGN;
  }
  function selectedDesignKey(){
    var s = document.getElementById('designPick');
    return (s && DESIGNS[s.value]) ? s.value : 'official';
  }
  (function(){
    var s = document.getElementById('designPick');
    if(!s) return;
    try{ var saved = localStorage.getItem('reportDesign'); if(saved && DESIGNS[saved]) s.value = saved; }catch(e){}
    s.addEventListener('change', function(){ try{ localStorage.setItem('reportDesign', s.value); }catch(e){} });
  })();
  var LOGO_B64 = "";
  var topLogo = document.getElementById('topLogo'); if(topLogo) topLogo.src = 'data:image/png;base64,' + LOGO_B64;

  var toastEl = document.getElementById('toast');
  var toastTimer = null;
  function showToast(msg, ms){ toastEl.textContent = msg; toastEl.classList.add('show'); clearTimeout(toastTimer); toastTimer = setTimeout(function(){ toastEl.classList.remove('show'); }, ms || 2600); }
  function errDetail(err){
    var s = err ? ((err.name ? err.name + ': ' : '') + (err.message || String(err))) : 'unknown';
    var line = err && err.stack ? String(err.stack).split('\n').slice(0,2).join(' | ') : '';
    return ' [' + s + (line ? ' @ ' + line : '') + ']';
  }

  function loadSchedule(){
    try{
      var raw = localStorage.getItem(SCHED_KEY);
      if(raw) return JSON.parse(raw);
    }catch(e){}
    return DEFAULT_SCHEDULE;
  }
  function saveSchedule(sched){
    try{ localStorage.setItem(SCHED_KEY, JSON.stringify(sched)); }catch(e){}
  }
  var schedule = loadSchedule();

  // ---- render schedule settings ----
  var schedGrid = document.getElementById('schedGrid');
  function renderSchedGrid(){
    schedGrid.innerHTML = '';
    schedule.forEach(function(pair, i){
      var wrap = document.createElement('div');
      wrap.className = 'sched-item';
      var lbl = document.createElement('label');
      lbl.textContent = 'الحصة ' + ORDINALS[i];
      var row = document.createElement('div');
      row.className = 'row';
      var fromInp = document.createElement('input');
      fromInp.type = 'time'; fromInp.value = pair[0];
      var toInp = document.createElement('input');
      toInp.type = 'time'; toInp.value = pair[1];
      fromInp.addEventListener('change', function(){ schedule[i][0] = fromInp.value; saveSchedule(schedule); refreshAllPeriodEchoes(); });
      toInp.addEventListener('change', function(){ schedule[i][1] = toInp.value; saveSchedule(schedule); refreshAllPeriodEchoes(); });
      row.appendChild(toInp); row.appendChild(fromInp);
      wrap.appendChild(lbl); wrap.appendChild(row);
      schedGrid.appendChild(wrap);
    });
  }
  renderSchedGrid();

  // ---- school identity (school name + principal), persisted locally ----
  var SCHOOL_KEY = 'report21-school-identity-v1';
  var DEFAULT_IDENTITY = { school: 'المتوسطة الحادية والعشرون', principal: 'أمينة آل مشيط' };
  function loadIdentity(){
    try{
      var raw = localStorage.getItem(SCHOOL_KEY);
      if(raw) return JSON.parse(raw);
    }catch(e){}
    return DEFAULT_IDENTITY;
  }
  function saveIdentity(id){
    try{ localStorage.setItem(SCHOOL_KEY, JSON.stringify(id)); }catch(e){}
  }
  var schoolIdentity = loadIdentity();
  var f_school = document.getElementById('f_school');
  var f_principal = document.getElementById('f_principal');
  f_school.value = schoolIdentity.school;
  f_principal.value = schoolIdentity.principal;
  f_school.addEventListener('change', function(){ schoolIdentity.school = f_school.value.trim() || DEFAULT_IDENTITY.school; saveIdentity(schoolIdentity); });
  f_principal.addEventListener('change', function(){ schoolIdentity.principal = f_principal.value.trim() || DEFAULT_IDENTITY.principal; saveIdentity(schoolIdentity); });

  function periodsLabel(selected){
    if(!selected.length) return '';
    var names = selected.map(function(n){ return ORDINALS[n-1]; });
    if(names.length === 1) return names[0];
    return names.slice(0,-1).join('، ') + ' و' + names[names.length-1];
  }
  function periodsTimeRange(selected){
    if(!selected.length) return null;
    var starts = selected.map(function(n){ return schedule[n-1][0]; });
    var ends = selected.map(function(n){ return schedule[n-1][1]; });
    starts.sort(); ends.sort();
    return { from: starts[0], to: ends[ends.length-1] };
  }

  // ============================================================
  // Session cards
  // ============================================================
  var sessionsWrap = document.getElementById('sessionsWrap');
  var tpl = document.getElementById('sessionTemplate');
  var sessionEls = [];

  function renumberSessions(){
    sessionEls.forEach(function(el, i){
      el.querySelector('.num').textContent = 'الحصة رقم ' + (i+1) + ' في اليوم';
    });
  }

  function refreshAllPeriodEchoes(){
    sessionEls.forEach(function(el){ updatePeriodEcho(el); });
  }

  function updatePeriodEcho(el){
    var selected = Array.prototype.slice.call(el.querySelectorAll('.period-chip.active')).map(function(c){ return parseInt(c.dataset.p,10); }).sort(function(a,b){return a-b;});
    var echo = el.querySelector('.period-time-echo');
    if(!selected.length){ echo.textContent = ''; return; }
    var range = periodsTimeRange(selected);
    echo.textContent = 'الحصة ' + periodsLabel(selected) + '  —  الوقت: ' + range.from + ' – ' + range.to;
  }

  function addSession(prefill){
    var node = tpl.content.cloneNode(true);
    var el = node.querySelector('.session');
    sessionsWrap.appendChild(el);
    sessionEls.push(el);

    // period picker
    var picker = el.querySelector('.period-picker');
    for(var p=1; p<=8; p++){
      (function(p){
        var chip = document.createElement('div');
        chip.className = 'period-chip';
        chip.textContent = ORDINALS[p-1];
        chip.dataset.p = p;
        chip.addEventListener('click', function(){
          chip.classList.toggle('active');
          updatePeriodEcho(el);
        });
        picker.appendChild(chip);
      })(p);
    }

    el.querySelector('.removeBtn').addEventListener('click', function(){
      sessionsWrap.removeChild(el);
      sessionEls = sessionEls.filter(function(x){ return x!==el; });
      renumberSessions();
    });

    if(prefill){
      if(prefill.subject) el.querySelector('.f_subject').value = prefill.subject;
      if(prefill.stage) el.querySelector('.f_stage').value = prefill.stage;
      if(prefill.klass) el.querySelector('.f_class').value = prefill.klass;
      if(prefill.total) el.querySelector('.f_total').value = prefill.total;
      if(prefill.present) el.querySelector('.f_present').value = prefill.present;
      if(prefill.lesson) el.querySelector('.f_lesson').value = prefill.lesson;
      if(prefill.notes) el.querySelector('.f_notes').value = prefill.notes;
      if(prefill.link) el.querySelector('.f_link').value = prefill.link;
      if(prefill.names) el.querySelector('.f_names').value = prefill.names;
      if(prefill.periods && prefill.periods.length){
        prefill.periods.forEach(function(p){
          var chip = picker.querySelector('.period-chip[data-p="'+p+'"]');
          if(chip) chip.classList.add('active');
        });
        updatePeriodEcho(el);
      }
      if(prefill.day) document.getElementById('f_day').value = prefill.day;
      if(prefill.date) document.getElementById('f_date').value = prefill.date;
      if(prefill.week) document.getElementById('f_week').value = prefill.week;
      if(prefill.teacher) document.getElementById('f_teacher').value = prefill.teacher;
    }

    renumberSessions();
    return el;
  }

  document.getElementById('addSessionBtn').addEventListener('click', function(){ addSession(); });
  addSession(); // start with one

  // ============================================================
  // Excel/CSV import — flexible header matching + period parsing
  // ============================================================
  var FIELD_ALIASES = {
    date:    ['التاريخ الهجري','التاريخ','تاريخ'],
    day:     ['اليوم','يوم'],
    week:    ['الأسبوع الدراسي','الأسبوع','أسبوع'],
    subject: ['المادة','اسم المادة','مادة'],
    stage:   ['المرحلة الدراسية','المرحلة/الصف','المرحلة','الصف'],
    klass:   ['الفصل','فصل','الشعبة'],
    period:  ['الحصة','رقم الحصة','حصة'],
    lesson:  ['عنوان الدرس','الدرس','عنوان','موضوع الدرس'],
    total:   ['عدد الطالبات الكلي','عدد الطالبات','الطالبات الكلي','إجمالي الطالبات','عدد الطلاب'],
    present: ['عدد الحاضرات الفعلي','عدد الحاضرات','الحاضرات','عدد الحضور'],
    link:    ['رابط شواهد الحصة','رابط الشواهد','الرابط','شواهد الحصة','شواهد'],
    notes:   ['ملاحظات وتوصيات','ملاحظات','الملاحظات','ملاحظة'],
  };
  function normalizeHeader(s){
    return String(s).trim().replace(/\s+/g,' ').replace(/[\u064B-\u065F]/g,'');
  }
  var COL_LOOKUP = {};
  Object.keys(FIELD_ALIASES).forEach(function(field){
    FIELD_ALIASES[field].forEach(function(alias){ COL_LOOKUP[normalizeHeader(alias)] = field; });
  });

  function parsePeriodsValue(raw){
    if(!raw) return [];
    raw = String(raw).trim();
    var nums = raw.match(/\d+/g);
    if(nums && nums.length){
      return nums.map(Number).filter(function(n){ return n>=1 && n<=8; });
    }
    var tokens = raw.replace(/^الحصة\s*/,'').split(/[و,،]+/).map(function(s){ return s.trim(); }).filter(Boolean);
    var result = [];
    tokens.forEach(function(tok){
      var idx = ORDINALS.indexOf(tok);
      if(idx === -1){
        for(var i=0;i<ORDINALS.length;i++){
          if(tok.indexOf(ORDINALS[i]) !== -1 || ORDINALS[i].indexOf(tok) !== -1){ idx=i; break; }
        }
      }
      if(idx !== -1) result.push(idx+1);
    });
    return result;
  }

  function isSessionEmpty(el){
    return !el.querySelector('.f_subject').value.trim() &&
           !el.querySelector('.f_total').value.trim() &&
           !el.querySelector('.f_lesson').value.trim();
  }

  function importWorkbookFile(file){
    var reader = new FileReader();
    reader.onload = function(e){
      try{
        var data = new Uint8Array(e.target.result);
        var wb = XLSX.read(data, {type:'array'});
        var sheetName = wb.SheetNames.indexOf('سجل الحصص') !== -1 ? 'سجل الحصص' : wb.SheetNames[0];
        var sheet = wb.Sheets[sheetName];
        var rows = XLSX.utils.sheet_to_json(sheet, {defval:''});
        var added = 0;
        if(sessionEls.length === 1 && isSessionEmpty(sessionEls[0])){
          sessionsWrap.removeChild(sessionEls[0]);
          sessionEls = [];
        }
        rows.forEach(function(row){
          var mapped = {};
          Object.keys(row).forEach(function(k){
            var key = COL_LOOKUP[normalizeHeader(k)];
            if(key && String(row[k]).trim() !== '') mapped[key] = String(row[k]).trim();
          });
          if(!mapped.subject && !mapped.total && !mapped.lesson) return; // skip empty/example-less rows
          if(mapped.period){ mapped.periods = parsePeriodsValue(mapped.period); }
          addSession(mapped);
          added++;
        });
        if(sessionEls.length === 0) addSession();
        showToast(added ? ('تم استيراد ' + added + ' حصة') : 'لم يتم العثور على صفوف صالحة');
      }catch(err){
        console.error(err);
        showToast('تعذّر قراءة الملف — تأكدي من التنسيق');
      }
    };
    reader.readAsArrayBuffer(file);
  }

  // ============================================================
  // Teams / مدرستي meeting-attendance CSV import
  // ============================================================
  var AR_DAYS = ['الأحد','الاثنين','الثلاثاء','الأربعاء','الخميس','الجمعة','السبت'];
  function pad2(n){ return (n<10?'0':'')+n; }

  function toHijriString(date){
    try{
      var fmt = new Intl.DateTimeFormat('en-u-ca-islamic-umalqura', {year:'numeric',month:'2-digit',day:'2-digit'});
      var parts = fmt.formatToParts(date);
      var y = parts.filter(function(p){return p.type==='year';})[0].value;
      var m = parts.filter(function(p){return p.type==='month';})[0].value;
      var d = parts.filter(function(p){return p.type==='day';})[0].value;
      return y + '/' + (m.length<2?'0'+m:m) + '/' + (d.length<2?'0'+d:d);
    }catch(e){ return ''; }
  }

  function parseTeamsAttendanceText(text){
    var lines = text.split(/\r\n|\n/);
    var result = { lesson:'', names:[], dateStr:'', dayName:'', startTime:'', endTime:'', startRaw:'', endRaw:'' };
    var section = 0, headerCols = null, roleIdx = -1;
    for(var i=0;i<lines.length;i++){
      var line = lines[i];
      if(/^1[.\u066B]?\s*الملخص/.test(line)){ section=1; continue; }
      if(/^2[.\u066B]?\s*المشاركون/.test(line)){ section=2; headerCols=null; continue; }
      if(/^3[.\u066B]?\s*/.test(line)){ section=3; continue; }
      if(section===1){
        var p1 = line.split('\t');
        if(p1[0] && p1[0].trim()==='عنوان الاجتماع') result.lesson = (p1[1]||'').trim();
        if(p1[0] && p1[0].trim()==='وقت البدء') result.startRaw = (p1[1]||'').trim();
        if(p1[0] && p1[0].trim()==='وقت الانتهاء') result.endRaw = (p1[1]||'').trim();
      } else if(section===2){
        if(!line.trim()) continue;
        var cols = line.split('\t');
        if(cols[0] && cols[0].trim()==='الاسم'){ headerCols = cols; roleIdx = cols.indexOf('الدور'); continue; }
        if(!headerCols) continue;
        var role = roleIdx>=0 ? (cols[roleIdx]||'').trim() : '';
        if(cols[0] && role.indexOf('المنظم') === -1){
          result.names.push(cols[0].trim());
        }
      }
    }
    if(result.startRaw){
      var d = new Date(result.startRaw.replace(',', ''));
      if(!isNaN(d.getTime())){
        var dow = d.getDay();
        if(dow>=0 && dow<=4) result.dayName = AR_DAYS[dow];
        result.dateStr = toHijriString(d);
        result.startTime = pad2(d.getHours())+':'+pad2(d.getMinutes());
      }
    }
    if(result.endRaw){
      var d2 = new Date(result.endRaw.replace(',', ''));
      if(!isNaN(d2.getTime())) result.endTime = pad2(d2.getHours())+':'+pad2(d2.getMinutes());
    }
    return result;
  }

  function importTeamsCsvFile(file){
    var reader = new FileReader();
    reader.onload = function(e){
      try{
        var bytes = new Uint8Array(e.target.result);
        var text;
        // BOM-based UTF-16 detection (Teams exports are UTF-16LE)
        if(bytes[0]===0xFF && bytes[1]===0xFE){
          text = new TextDecoder('utf-16le').decode(bytes);
        } else if(bytes[0]===0xFE && bytes[1]===0xFF){
          text = new TextDecoder('utf-16be').decode(bytes);
        } else {
          text = new TextDecoder('utf-8').decode(bytes);
        }
        var parsed = parseTeamsAttendanceText(text);
        if(!parsed.names.length){
          showToast('ما قدرت أوجد قائمة مشاركين بهذا الملف');
          return;
        }
        if(sessionEls.length === 1 && isSessionEmpty(sessionEls[0])){
          sessionsWrap.removeChild(sessionEls[0]);
          sessionEls = [];
        }
        var el = addSession({
          lesson: parsed.lesson,
          present: parsed.names.length,
          names: parsed.names.join('\n'),
          day: parsed.dayName,
          date: parsed.dateStr,
        });
        if(parsed.startTime && parsed.endTime){
          showToast('تم الاستيراد — وقت الاجتماع الفعلي ' + parsed.startTime + ' – ' + parsed.endTime + '، اختاري الحصة المطابقة');
        } else {
          showToast('تم استيراد بيانات الحضور من ملف Teams');
        }
      }catch(err){
        console.error(err);
        showToast('تعذّر قراءة ملف الحضور — تأكدي من أنه تصدير Teams/مدرستي');
      }
    };
    reader.readAsArrayBuffer(file);
  }

  // بيانات الحصص لا تُمسح إلا عند إغلاق الصفحة أو عند استيراد ملف جديد (هنا).
  function clearSessionsForNewImport(){
    sessionEls.forEach(function(el){ sessionsWrap.removeChild(el); });
    sessionEls = [];
    addSession(); // بطاقة فارغة تُستبدل بأول حصة مستوردة
  }

  document.getElementById('importTeamsCsv').addEventListener('change', function(e){
    var f = e.target.files[0];
    if(f){ clearSessionsForNewImport(); importTeamsCsvFile(f); }
    e.target.value = '';
  });

  // اختيار مجلد كامل (webkitdirectory) غير مدعوم في متصفحات الجوال — نخفي الزر ونُبقي زر «عدة ملفات».
  (function(){
    var folderInput = document.getElementById('importFolder');
    var supportsDir = 'webkitdirectory' in folderInput && !/Android|iPhone|iPad|iPod|Mobile/i.test(navigator.userAgent);
    if(!supportsDir && folderInput.parentNode) folderInput.parentNode.style.display = 'none';
  })();

  ['importFolder','importMultiFiles'].forEach(function(id){
  document.getElementById(id).addEventListener('change', function(e){
    var allFiles = Array.prototype.slice.call(e.target.files);
    var xlsxFiles = allFiles.filter(function(f){ return /\.xlsx?$/i.test(f.name); });
    var csvFiles = allFiles.filter(function(f){ return /\.csv$/i.test(f.name); });
    if(!xlsxFiles.length && !csvFiles.length){ showToast('ما فيه ملفات إكسل أو CSV في هذا المجلد'); return; }
    clearSessionsForNewImport();
    xlsxFiles.forEach(importWorkbookFile);
    csvFiles.forEach(importTeamsCsvFile);
    e.target.value = '';
  });
  });

  // ============================================================
  // Data collection & validation
  // ============================================================
  function collectShared(){
    return {
      teacher: (document.getElementById('f_teacher').value.trim()) || '[اسم المعلمة]',
      week: document.getElementById('f_week').value.trim(),
      day: document.getElementById('f_day').value,
      date: document.getElementById('f_date').value.trim(),
      school: document.getElementById('f_school').value.trim() || DEFAULT_IDENTITY.school,
      principal: document.getElementById('f_principal').value.trim() || DEFAULT_IDENTITY.principal,
    };
  }

  function collectSession(el, shared){
    var selected = Array.prototype.slice.call(el.querySelectorAll('.period-chip.active')).map(function(c){ return parseInt(c.dataset.p,10); }).sort(function(a,b){return a-b;});
    var range = periodsTimeRange(selected);
    var total = parseInt(el.querySelector('.f_total').value || '0', 10) || 0;
    var present = parseInt(el.querySelector('.f_present').value || '0', 10) || 0;
    return {
      teacher: shared.teacher, week: shared.week, day: shared.day, date: shared.date,
      school: shared.school, principal: shared.principal,
      subject: el.querySelector('.f_subject').value.trim(),
      stage: el.querySelector('.f_stage').value.trim(),
      klass: el.querySelector('.f_class').value.trim(),
      period: selected.length ? periodsLabel(selected) : '',
      from: range ? range.from : '', to: range ? range.to : '',
      lesson: el.querySelector('.f_lesson').value.trim(),
      total: total, present: present,
      names: el.querySelector('.f_names').value.split('\n').map(function(s){return s.trim();}).filter(Boolean),
      link: el.querySelector('.f_link').value.trim(),
      notes: el.querySelector('.f_notes').value.trim(),
    };
  }

  function validateAll(sessions){
    var errEl = document.getElementById('errMsg');
    errEl.classList.remove('show');
    if(!sessions.length){ errEl.textContent = 'أضيفي حصة واحدة على الأقل.'; errEl.classList.add('show'); return false; }
    for(var i=0;i<sessions.length;i++){
      var s = sessions[i];
      if(!s.subject || s.total<=0){
        errEl.textContent = 'الحصة رقم ' + (i+1) + ': تأكدي من تعبئة المادة وعدد الطالبات الكلي على الأقل.';
        errEl.classList.add('show');
        return false;
      }
    }
    return true;
  }

  // ============================================================
  // Report archive: local log + Google Sheet sync (via Apps Script web app)
  // ============================================================
  var LOG_KEY = 'report21-log-v1';
  // رابط تطبيق الويب (Google Apps Script) الخاص بالمدير — ضعيه هنا؛ إن تُرك فارغًا يبقى السجل على الجهاز فقط.
  var SHEET_URL = 'https://script.google.com/macros/s/AKfycbzvH02sKzkyp2od71JJOCKBiHw-w-KQ_L0SeJJe89xNmbw-PY-5gGYd9axH3zApHQubGA/exec';
  var LOG_SHEET_NAME = 'سجل الحصص';
  // Header names double as the import aliases, so an exported/synced sheet can be re-imported as-is.
  var LOG_COLS = [
    ['التاريخ الهجري', function(r){ return r.date; }],
    ['اليوم', function(r){ return r.day; }],
    ['الأسبوع الدراسي', function(r){ return r.week; }],
    ['المعلمة', function(r){ return r.teacher; }],
    ['المادة', function(r){ return r.subject; }],
    ['المرحلة الدراسية', function(r){ return r.stage; }],
    ['الفصل', function(r){ return r.klass; }],
    ['الحصة', function(r){ return r.period; }],
    ['من', function(r){ return r.from; }],
    ['إلى', function(r){ return r.to; }],
    ['عنوان الدرس', function(r){ return r.lesson; }],
    ['عدد الطالبات الكلي', function(r){ return r.total; }],
    ['عدد الحاضرات الفعلي', function(r){ return r.present; }],
    ['نسبة الحضور', function(r){ return r.total ? Math.round(r.present / r.total * 100) + '%' : ''; }],
    ['رابط شواهد الحصة', function(r){ return r.link; }],
    ['ملاحظات وتوصيات', function(r){ return r.notes; }],
    ['وقت التسجيل', function(r){ return r.savedAt; }],
    ['المدرسة', function(r){ return r.school; }],
    ['مديرة المدرسة', function(r){ return r.principal; }],
  ];
  var LOG_HEADERS = LOG_COLS.map(function(c){ return c[0]; }).concat(['المفتاح']);

  function loadLog(){
    try{ var raw = localStorage.getItem(LOG_KEY); if(raw) return JSON.parse(raw); }catch(e){}
    return [];
  }
  function saveLog(rows){
    try{ localStorage.setItem(LOG_KEY, JSON.stringify(rows)); }catch(e){}
  }
  function getSheetUrl(){
    return SHEET_URL;
  }
  function logKey(s){
    return [s.date, s.period, s.klass, s.subject, s.stage].concat(s.period ? [] : [s.lesson]).join('|');
  }
  function logRow(r){
    return LOG_COLS.map(function(c){ var v = c[1](r); return v == null ? '' : v; }).concat([r.key]);
  }

  function updateLogStatus(){
    var el = document.getElementById('logStatus');
    if(!el) return;
    var rows = loadLog();
    var pending = rows.filter(function(r){ return !r.synced; }).length;
    var url = getSheetUrl();
    el.textContent = 'المحفوظ في السجل: ' + rows.length + ' حصة' +
      (url ? (pending ? ' — بانتظار الإرسال إلى الشيت: ' + pending : ' — كلها مرسلة إلى الشيت') : ' — الشيت غير مربوط (السجل محفوظ على جهازك فقط)');
  }

  async function postRowsToSheet(url, rows){
    var body = JSON.stringify({ sheet: LOG_SHEET_NAME, headers: LOG_HEADERS, rows: rows.map(logRow) });
    var opts = { method: 'POST', headers: { 'Content-Type': 'text/plain;charset=utf-8' }, body: body };
    try{
      var res = await fetch(url, opts);
      var j = await res.json();
      return j && j.ok ? 'ok' : 'fail';
    }catch(e){
      // Response unreadable (CORS) — the request may still have gone through; the sheet script upserts, so resending is safe.
      try{ await fetch(url, { method: 'POST', mode: 'no-cors', headers: opts.headers, body: body }); return 'unconfirmed'; }
      catch(e2){ return 'fail'; }
    }
  }

  var syncing = false;
  async function syncLog(){
    var url = getSheetUrl();
    if(!url || syncing) return null;
    var rows = loadLog();
    var pending = rows.filter(function(r){ return !r.synced; });
    if(!pending.length) return { sent: 0, failed: 0 };
    syncing = true;
    var status;
    try{ status = await postRowsToSheet(url, pending); }finally{ syncing = false; }
    if(status === 'fail') return { sent: 0, failed: pending.length };
    // Re-read so rows archived while the request was in flight are not overwritten.
    var sentKeys = {};
    pending.forEach(function(r){ sentKeys[r.key + '@' + r.savedAt] = true; });
    var fresh = loadLog();
    fresh.forEach(function(r){ if(sentKeys[r.key + '@' + r.savedAt]) r.synced = true; });
    saveLog(fresh);
    return { sent: pending.length, failed: 0, unconfirmed: status === 'unconfirmed' };
  }

  async function archiveSessions(sessions){
    var now = new Date().toISOString().slice(0, 16).replace('T', ' ');
    var rows = loadLog();
    sessions.forEach(function(s){
      var rec = {
        date: s.date, day: s.day, week: s.week, teacher: s.teacher, subject: s.subject, stage: s.stage, klass: s.klass,
        period: s.period, from: s.from, to: s.to, lesson: s.lesson, total: s.total, present: s.present,
        link: s.link, notes: s.notes, savedAt: now, school: s.school, principal: s.principal, synced: false,
      };
      rec.key = logKey(rec);
      var idx = -1;
      rows.forEach(function(r, i){ if(r.key === rec.key) idx = i; });
      if(idx >= 0) rows[idx] = rec; else rows.push(rec);
    });
    saveLog(rows);
    updateLogStatus();
    if(!getSheetUrl()) return;
    var r = await syncLog();
    updateLogStatus();
    if(r && r.failed) showToast('تعذّر الإرسال للشيت — البيانات محفوظة وستُرسل لاحقًا', 5000);
    else if(r) showToast('تم حفظ ' + sessions.length + ' حصة وإرسالها إلى الشيت' + (r.unconfirmed ? ' (تحققي من الشيت)' : ''), 4000);
  }

  updateLogStatus();
  window.addEventListener('online', function(){ syncLog().then(updateLogStatus); });
  syncLog().then(updateLogStatus);

  // ============================================================
  // docx helpers (teal/gray palette, ministry-aligned)
  // ============================================================
  function arText(text, opts){
    opts = opts || {};
    return new docx.TextRun({ text: text, font:{name:FONT, ascii:FONT, cs:FONT, hAnsi:FONT}, rightToLeft:true,
      language:{value:'ar-SA', bidirectional:'ar-SA'}, size:opts.size||16, bold:!!opts.bold, italics:!!opts.italics, color:opts.color||'000000' });
  }
  function arPara(text, opts){
    opts = opts || {};
    return new docx.Paragraph({ bidirectional:true, alignment: opts.align||docx.AlignmentType.RIGHT, spacing: opts.spacing||{after:70},
      pageBreakBefore: !!opts.pageBreakBefore,
      children: Array.isArray(text) ? text : [arText(text, opts)] });
  }
  function cellC(text, o){
    o = o || {};
    return new docx.TableCell({ width:{size:o.width, type:docx.WidthType.DXA}, shading: o.fill?{type:docx.ShadingType.CLEAR, fill:o.fill, color:'auto'}:undefined,
      verticalAlign: docx.VerticalAlign.CENTER, margins:{top:35,bottom:35,left:70,right:70},
      children:[arPara(text, {align:o.align||docx.AlignmentType.CENTER, spacing:{after:0}, bold:o.bold, color:o.color||'000000', size:o.size||16})] });
  }
  function headingBar(text, color, width){
    var w = width || CONTENT_WIDTH;
    return new docx.Table({ width:{size:w, type:docx.WidthType.DXA}, columnWidths:[w], visuallyRightToLeft:true,
      rows:[ new docx.TableRow({ children:[ new docx.TableCell({ width:{size:w,type:docx.WidthType.DXA}, shading:{type:docx.ShadingType.CLEAR, fill:color, color:'auto'},
        verticalAlign:docx.VerticalAlign.CENTER, margins:{top:40,bottom:40,left:100,right:100},
        children:[arPara(text, {align:docx.AlignmentType.CENTER, spacing:{after:0}, bold:true, color:'FFFFFF', size:16})] }) ] }) ] });
  }
  function infoGrid(pairs, color){
    var n = pairs.length, w = Math.floor(CONTENT_WIDTH/n);
    var widths = new Array(n).fill(w); widths[n-1] = CONTENT_WIDTH - w*(n-1);
    return new docx.Table({ width:{size:CONTENT_WIDTH,type:docx.WidthType.DXA}, columnWidths:widths, visuallyRightToLeft:true,
      rows:[
        new docx.TableRow({ children: pairs.map(function(p,i){ return cellC(p.label,{width:widths[i], bold:true, fill:color, color:'FFFFFF', size:16}); }) }),
        new docx.TableRow({ children: pairs.map(function(p,i){ return cellC(p.value,{width:widths[i], fill:TEAL_TINT, size:16}); }) }),
      ]});
  }
  function twoColTable(rows, headerFill, headerColor){
    var rW = Math.round(CONTENT_WIDTH*0.62), lW = CONTENT_WIDTH - rW;
    return new docx.Table({ width:{size:CONTENT_WIDTH,type:docx.WidthType.DXA}, columnWidths:[rW,lW], visuallyRightToLeft:true,
      rows: rows.map(function(r,i){
        var isHeader = i===0;
        var fill = isHeader ? (headerFill||TEAL_TINT) : (i%2===0?TEAL_TINT:'FFFFFF');
        var color = isHeader && headerFill ? (headerColor||'FFFFFF') : '000000';
        return new docx.TableRow({ children:[
          cellC(r.right,{width:rW, bold:r.bold||isHeader, fill:fill, color:color, align:docx.AlignmentType.RIGHT}),
          cellC(r.left,{width:lW, bold:r.bold||isHeader, fill:fill, color:color}),
        ]});
      })});
  }
  function bulletPara(text, color){
    return new docx.Paragraph({ bidirectional:true, alignment:docx.AlignmentType.RIGHT, spacing:{after:60},
      children:[ arText('• ',{bold:true,color:color||TEAL_DEEP,size:16}), arText(text,{size:16}) ] });
  }

  // ---- pie chart on canvas ----
  function drawPieChart(presentPct){
    var canvas = document.createElement('canvas');
    var W = 480, H = 400;
    canvas.width = W; canvas.height = H;
    var ctx = canvas.getContext('2d');
    ctx.fillStyle = '#ffffff'; ctx.fillRect(0,0,W,H);
    ctx.direction = 'rtl'; ctx.textAlign = 'center';
    ctx.fillStyle = DESIGN.pieTitle; ctx.font = '700 20px Tahoma, Arial, sans-serif';
    ctx.fillText('نسبة الحضور مقابل عدد الطالبات', W/2, 32);

    var cx = W/2, cy = 210, r = 130;
    var presentFrac = Math.max(0, Math.min(1, presentPct/100));
    var start = -Math.PI/2;
    var presentEnd = start + presentFrac*2*Math.PI;

    ctx.beginPath(); ctx.moveTo(cx,cy); ctx.arc(cx,cy,r,start,presentEnd); ctx.closePath();
    ctx.fillStyle = DESIGN.pieA; ctx.fill();
    ctx.beginPath(); ctx.moveTo(cx,cy); ctx.arc(cx,cy,r,presentEnd,start+2*Math.PI); ctx.closePath();
    ctx.fillStyle = DESIGN.pieB; ctx.fill();

    ctx.fillStyle = '#ffffff'; ctx.font = '700 19px Tahoma, Arial, sans-serif';
    var midPresent = start + (presentEnd-start)/2;
    ctx.fillText(Math.round(presentFrac*100) + '%', cx + Math.cos(midPresent)*r*0.6, cy + Math.sin(midPresent)*r*0.6 + 7);
    if(presentFrac < 0.97){
      var midAbsent = presentEnd + (2*Math.PI - (presentEnd-start))/2;
      ctx.fillText(Math.round((1-presentFrac)*100) + '%', cx + Math.cos(midAbsent)*r*0.75, cy + Math.sin(midAbsent)*r*0.75 + 7);
    }
    ctx.textAlign = 'right'; ctx.font = '600 14px Tahoma, Arial, sans-serif';
    ctx.fillStyle = DESIGN.pieA; ctx.fillRect(W-60, 350, 13, 13);
    ctx.fillStyle = '#20242B'; ctx.fillText('الحاضرات', W-78, 361);
    ctx.fillStyle = DESIGN.pieB; ctx.fillRect(W-180, 350, 13, 13);
    ctx.fillStyle = '#20242B'; ctx.fillText('المتغيبات', W-198, 361);
    return canvas;
  }

  function canvasToUint8Array(canvas){
    // Mobile browsers may return a null blob from toBlob (memory pressure) — fall back to toDataURL.
    function fromDataUrl(){
      return base64ToUint8Array(canvas.toDataURL('image/png').split(',')[1]);
    }
    return new Promise(function(resolve, reject){
      try{
        canvas.toBlob(function(blob){
          if(!blob){
            try{ resolve(fromDataUrl()); }catch(e){ reject(e); }
            return;
          }
          var reader = new FileReader();
          reader.onload = function(){ resolve(new Uint8Array(reader.result)); };
          reader.onerror = function(){ try{ resolve(fromDataUrl()); }catch(e){ reject(e); } };
          reader.readAsArrayBuffer(blob);
        }, 'image/png');
      }catch(e){
        try{ resolve(fromDataUrl()); }catch(e2){ reject(e2); }
      }
    });
  }

  // Never throws: an unusable link (too long for the QR encoder, no canvas support…) just yields no QR.
  function generateQrCanvas(link){
    // Draw the QR modules ourselves onto a fresh canvas: synchronous, no DOM/timer/image-load dependence
    // (the library's own canvas→img flow is async and unreliable on mobile browsers).
    return new Promise(function(resolve){
      try{
        var qr = new QRCode(document.createElement('div'), { text: link, width:200, height:200, correctLevel: QRCode.CorrectLevel.L });
        var model = qr._oQRCode, n = model.getModuleCount();
        var quiet = 2, cell = Math.max(3, Math.floor(400 / (n + quiet*2)));
        var size = (n + quiet*2) * cell;
        var c = document.createElement('canvas'); c.width = size; c.height = size;
        var ctx = c.getContext('2d');
        ctx.fillStyle = '#ffffff'; ctx.fillRect(0, 0, size, size);
        ctx.fillStyle = '#'+DESIGN.deep;
        for(var r=0;r<n;r++) for(var k=0;k<n;k++) if(model.isDark(r,k)) ctx.fillRect((k+quiet)*cell, (r+quiet)*cell, cell, cell);
        resolve(c);
      }catch(e){
        console.warn('QR generation failed', e);
        resolve(null);
      }
    });
  }

  // ---- attendance name list, compact multi-column if long ----
  function namesTable(names, width){
    var w = width || CONTENT_WIDTH;
    var perCol = names.length > 30 ? Math.ceil(names.length/3) : (names.length > 15 ? Math.ceil(names.length/2) : names.length);
    var numCols = Math.ceil(names.length / perCol);
    var colWidth = Math.floor(w / numCols);
    var rowsCount = perCol;
    var rows = [];
    // header
    var headerCells = [];
    for(var c=0;c<numCols;c++){
      headerCells.push(cellC('م', {width:Math.floor(colWidth*0.18), bold:true, fill:TEAL_DEEP, color:'FFFFFF', size:16}));
      headerCells.push(cellC('اسم الطالبة', {width:Math.floor(colWidth*0.82), bold:true, fill:TEAL_DEEP, color:'FFFFFF', align:docx.AlignmentType.RIGHT, size:16}));
    }
    rows.push(new docx.TableRow({children:headerCells}));
    for(var r=0;r<rowsCount;r++){
      var rowCells = [];
      for(var c2=0;c2<numCols;c2++){
        var idx = c2*perCol + r;
        var n = idx < names.length ? names[idx] : '';
        var num = idx < names.length ? String(idx+1) : '';
        var fill = (r%2===0)?TEAL_TINT:'FFFFFF';
        rowCells.push(cellC(num, {width:Math.floor(colWidth*0.18), fill:fill, size:16}));
        rowCells.push(cellC(n, {width:Math.floor(colWidth*0.82), fill:fill, align:docx.AlignmentType.RIGHT, size:16}));
      }
      rows.push(new docx.TableRow({children:rowCells}));
    }
    var widths = [];
    for(var c3=0;c3<numCols;c3++){ widths.push(Math.floor(colWidth*0.18), Math.floor(colWidth*0.82)); }
    return new docx.Table({ width:{size:w,type:docx.WidthType.DXA}, columnWidths:widths, visuallyRightToLeft:true, rows: rows });
  }

  // ---- build the paragraphs/tables for ONE session ----
  function base64ToUint8Array(b64){
    var bin = atob(b64);
    var arr = new Uint8Array(bin.length);
    for(var i=0;i<bin.length;i++) arr[i] = bin.charCodeAt(i);
    return arr;
  }

  var NOBORDER = {top:{style:docx.BorderStyle.SINGLE,size:2,color:'FFFFFF'},bottom:{style:docx.BorderStyle.SINGLE,size:2,color:'FFFFFF'},left:{style:docx.BorderStyle.SINGLE,size:2,color:'FFFFFF'},right:{style:docx.BorderStyle.SINGLE,size:2,color:'FFFFFF'},insideHorizontal:{style:docx.BorderStyle.SINGLE,size:2,color:'FFFFFF'},insideVertical:{style:docx.BorderStyle.SINGLE,size:2,color:'FFFFFF'}};

  // ---- inline letterhead: org text (right) + logo (left), together at page top ----
  function buildLetterhead(logoData, school){
    var rW = Math.round(CONTENT_WIDTH*0.58), lW = CONTENT_WIDTH - rW;
    return new docx.Table({ width:{size:CONTENT_WIDTH,type:docx.WidthType.DXA}, columnWidths:[rW, lW], visuallyRightToLeft:true,
      rows:[ new docx.TableRow({ children:[
        new docx.TableCell({ width:{size:rW,type:docx.WidthType.DXA}, verticalAlign:docx.VerticalAlign.CENTER, children:[
          arPara('المملكة العربية السعودية',{spacing:{after:6}, bold:true, size:DESIGN.lhSize}),
          arPara('وزارة التعليم',{spacing:{after:6}, bold:true, size:DESIGN.lhSize}),
          arPara('إدارة التعليم بمنطقة عسير',{spacing:{after:6}, bold:true, size:DESIGN.lhSize}),
          arPara(school,{spacing:{after:0}, bold:true, size:DESIGN.lhSize, color:TEAL_DEEP}),
        ]}),
        new docx.TableCell({ width:{size:lW,type:docx.WidthType.DXA}, verticalAlign:docx.VerticalAlign.CENTER, margins:{top:0,bottom:0,left:40,right:40}, children:[
          new docx.Paragraph({ alignment:docx.AlignmentType.CENTER, children:[ new docx.ImageRun({ type:'png', data:logoData, transformation:{width:DESIGN.logoW,height:DESIGN.logoH} }) ] })
        ]}),
      ]})]});
  }

  async function buildSessionChildren(d, isFirst, logoData){
    var children = [];

    children.push(new docx.Paragraph({pageBreakBefore: !isFirst, spacing:{after:60}, children:[]}));
    children.push(buildLetterhead(logoData, d.school));
    children.push(new docx.Paragraph({spacing:{after:60}, children:[]}));

    children.push(arPara([arText('تقرير المعلمة: ',{bold:true,size:DESIGN.titleSize,color:TEAL_DEEP}), arText(d.teacher,{bold:true,size:DESIGN.titleSize,color:TEAL}), arText(' في منصة مدرستي',{bold:true,size:DESIGN.titleSize,color:TEAL_DEEP})], {align:docx.AlignmentType.CENTER, spacing:{after:90}}));

    children.push(infoGrid([
      {label:'المادة', value:d.subject||'—'},
      {label:'المرحلة الدراسية', value:d.stage||'—'},
      {label:'الفصل', value:d.klass||'—'},
      {label:'الحصة', value:d.period||'—'},
    ], TEAL));
    children.push(new docx.Paragraph({spacing:{after:4}, children:[]}));
    children.push(infoGrid([
      {label:'الأسبوع الدراسي', value:d.week||'—'},
      {label:'اليوم', value:d.day||'—'},
      {label:'التاريخ الهجري', value:(d.date?d.date+' هـ':'—')},
      {label:'وقت الحصة', value:(d.from&&d.to)?(d.from+' — '+d.to):'—'},
    ], TEAL));
    children.push(new docx.Paragraph({spacing:{after:90}, children:[]}));
    if(d.lesson) children.push(arPara(d.lesson, {align:docx.AlignmentType.CENTER, spacing:{after:90}, bold:true, size:DESIGN.lessonSize, color:DESIGN.lesson}));

    var pct = d.total>0 ? Math.round((d.present/d.total)*1000)/10 : 0;
    children.push(headingBar('إحصائية الحضور', TEAL));
    children.push(twoColTable([
      {right:'البيان', left:'العدد'},
      {right:'عدد الطالبات الكلي', left:String(d.total)},
      {right:'عدد الحاضرات الفعلي', left:String(d.present)},
      {right:'نسبة الحضور', left: pct+'٪'},
    ], DESIGN.statFill, DESIGN.statColor));
    children.push(new docx.Paragraph({spacing:{after:90}, children:[]}));

    // ---- two columns: names (right) + pie chart (left), side by side like the reference ----
    var pieCanvas = drawPieChart(pct);
    var pieData = await canvasToUint8Array(pieCanvas);
    var rW2 = Math.round(CONTENT_WIDTH*0.55), lW2 = CONTENT_WIDTH - rW2;
    var rightCellChildren = [];
    if(d.names.length){
      rightCellChildren.push(headingBar('أسماء الطالبات الحاضرات', NAVY, rW2));
      rightCellChildren.push(namesTable(d.names, rW2));
    } else {
      rightCellChildren.push(new docx.Paragraph({spacing:{after:0}, children:[]}));
    }
    var twoCol = new docx.Table({ width:{size:CONTENT_WIDTH,type:docx.WidthType.DXA}, columnWidths:[rW2, lW2], visuallyRightToLeft:true,
      rows:[ new docx.TableRow({ children:[
        new docx.TableCell({ width:{size:rW2,type:docx.WidthType.DXA}, verticalAlign:docx.VerticalAlign.TOP, children: rightCellChildren }),
        new docx.TableCell({ width:{size:lW2,type:docx.WidthType.DXA}, verticalAlign:docx.VerticalAlign.CENTER, children:[
          new docx.Paragraph({ alignment:docx.AlignmentType.CENTER, children:[ new docx.ImageRun({type:'png', data:pieData, transformation:{width:200,height:167}}) ] })
        ]}),
      ]})]});
    children.push(twoCol);
    children.push(new docx.Paragraph({spacing:{after:90}, children:[]}));

    // ---- combined "شواهد الحصة" + "ملاحظات وتوصيات" bar ----
    if(d.link || d.notes){
      var barLabel = (d.link && d.notes) ? DESIGN.evidLabel + ' وملاحظات وتوصيات' : (d.link ? DESIGN.evidLabel : 'ملاحظات وتوصيات');
      children.push(headingBar(barLabel, TEAL2));
      children.push(new docx.Paragraph({spacing:{before:60,after:0}, children:[]}));
      if(d.link){
        var qrCanvas = await generateQrCanvas(d.link);
        var qrData = null;
        try{ if(qrCanvas) qrData = await canvasToUint8Array(qrCanvas); }catch(e){ console.warn(e); }
        if(qrData){
          children.push(new docx.Paragraph({ alignment:docx.AlignmentType.CENTER, spacing:{after:60}, children:[ new docx.ImageRun({type:'png', data:qrData, transformation:{width:80,height:80}}) ] }));
        }
      }
      if(d.notes){
        children.push(bulletPara(d.notes, TEAL_DEEP));
      }
      children.push(new docx.Paragraph({spacing:{after:90}, children:[]}));
    }

    // ---- signature row: plain text, no borders ----
    var halfW = Math.round(CONTENT_WIDTH*0.5);
    children.push(new docx.Table({ width:{size:CONTENT_WIDTH,type:docx.WidthType.DXA}, columnWidths:[halfW, CONTENT_WIDTH-halfW], visuallyRightToLeft:true,
      rows:[ new docx.TableRow({ children:[
        cellC('مديرة المدرسة: '+d.principal, {width:halfW, align:docx.AlignmentType.RIGHT, bold:true, size:16, fill:'FFFFFF'}),
        cellC('المعلمة: '+d.teacher, {width:CONTENT_WIDTH-halfW, align:docx.AlignmentType.LEFT, bold:true, size:16, fill:'FFFFFF'}),
      ]})]}));

    return children;
  }

  document.getElementById('genBtn').addEventListener('click', async function(){
    var shared = collectShared();
    var sessions = sessionEls.map(function(el){ return collectSession(el, shared); });
    if(!validateAll(sessions)) return;

    var btn = document.getElementById('genBtn');
    btn.disabled = true; btn.textContent = 'جارٍ التوليد…';
    try{
      applyDesign(selectedDesignKey());
      var logoData = base64ToUint8Array(LOGO_B64);
      var allChildren = [];
      for(var i=0;i<sessions.length;i++){
        var part = await buildSessionChildren(sessions[i], i===0, logoData);
        allChildren = allChildren.concat(part);
      }
      var doc = new docx.Document({
        styles:{ default:{ document:{ run:{ font:{name:FONT,ascii:FONT,cs:FONT,hAnsi:FONT}, size:16, rightToLeft:true, language:{value:'ar-SA', bidirectional:'ar-SA'} } } } },
        sections:[{
          properties:{ page:{ size:{width:11906,height:16838}, margin:DESIGN.margins } },
          children: allChildren,
        }],
      });
      var blob = await docx.Packer.toBlob(doc);
      var filename = 'تقرير_الحصص_' + (shared.date||new Date().toISOString().slice(0,10)).replace(/\//g,'-') + '.docx';
      var downloads = null;
      try{
        if(window.claude && typeof window.claude.use === 'function'){
          downloads = await window.claude.use('downloads');
        }
      }catch(e){ downloads = null; }
      if(downloads){
        var result = await downloads.save({ filename: filename, data: blob });
        if(result.status==='saved'){ showToast('تم إنشاء التقرير (' + sessions.length + ' حصة) وحفظه'); archiveSessions(sessions); }
      } else {
        var a = document.createElement('a');
        var url = URL.createObjectURL(blob);
        a.href = url; a.download = filename; a.style.display = 'none';
        document.body.appendChild(a);
        a.click();
        setTimeout(function(){ document.body.removeChild(a); URL.revokeObjectURL(url); }, 60000);
        showToast('تم إنشاء التقرير');
        archiveSessions(sessions);
      }
    }catch(err){
      console.error(err);
      showToast('حدث خطأ أثناء توليد التقرير' + errDetail(err), 15000);
    }finally{
      btn.disabled = false; btn.textContent = 'أ) ملف Word لكل الحصص';
    }
  });

  // ============================================================
  // PDF (print) generation — HTML mirror of the Word layout
  // ============================================================
  function esc(s){
    return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
  }

  function namesHtmlTable(names){
    if(!names.length) return '';
    var perCol = names.length > 24 ? Math.ceil(names.length/3) : (names.length > 12 ? Math.ceil(names.length/2) : names.length);
    var numCols = Math.ceil(names.length / perCol);
    var colsHtml = '';
    for(var c=0;c<numCols;c++){
      var rowsHtml = '';
      for(var r=0;r<perCol;r++){
        var idx = c*perCol + r;
        if(idx >= names.length) break;
        rowsHtml += '<tr><td class="pnum">'+(idx+1)+'</td><td class="pname">'+esc(names[idx])+'</td></tr>';
      }
      colsHtml += '<table class="names-tbl"><tr><th class="pnum">م</th><th class="pname">اسم الطالبة</th></tr>'+rowsHtml+'</table>';
    }
    return '<div class="names-cols">'+colsHtml+'</div>';
  }

  async function buildSessionHtml(d, logoDataUrl){
    var pct = d.total>0 ? Math.round((d.present/d.total)*1000)/10 : 0;
    var pieCanvas = drawPieChart(pct);
    var pieUrl = pieCanvas.toDataURL('image/png');
    var qrImg = '';
    if(d.link){
      var qrCanvas = await generateQrCanvas(d.link);
      try{
        d.qrOk = !!qrCanvas;
        if(qrCanvas) qrImg = '<img src="'+qrCanvas.toDataURL('image/png')+'" style="width:78px;height:78px;display:block;margin:6px auto;">';
      }catch(e){ console.warn(e); }
    }
    var namesHtml = d.names.length ? (
      '<div class="p-heading" style="background:var(--names);">أسماء الطالبات الحاضرات</div>' + namesHtmlTable(d.names)
    ) : '<div></div>';

    var shawahedBlock = '';
    if(d.link || d.notes){
      var barLabel = (d.link && d.notes) ? DESIGN.evidLabel + ' وملاحظات وتوصيات' : (d.link ? DESIGN.evidLabel : 'ملاحظات وتوصيات');
      shawahedBlock =
        '<div class="p-heading" style="background:var(--evid);">'+barLabel+'</div>' +
        qrImg +
        (d.notes ? '<p class="p-note">• '+esc(d.notes)+'</p>' : '');
    }

    return (
      '<div class="print-session"><div class="ps-in">' +
        '<table class="p-letterhead"><tr>' +
          '<td class="lh-text">' +
            '<div>المملكة العربية السعودية</div><div>وزارة التعليم</div>' +
            '<div>إدارة التعليم بمنطقة عسير</div><div style="color:var(--deep)">'+esc(d.school)+'</div>' +
          '</td>' +
          '<td class="lh-logo"><img src="'+logoDataUrl+'" style="width:'+DESIGN.logoW+'px;"></td>' +
        '</tr></table>' +
        '<h2 class="p-title">تقرير المعلمة: <span style="color:var(--main)">'+esc(d.teacher)+'</span> في منصة مدرستي</h2>' +
        '<table class="p-grid"><tr><th>المادة</th><th>المرحلة الدراسية</th><th>الفصل</th><th>الحصة</th></tr>' +
        '<tr><td>'+esc(d.subject||'—')+'</td><td>'+esc(d.stage||'—')+'</td><td>'+esc(d.klass||'—')+'</td><td>'+esc(d.period||'—')+'</td></tr></table>' +
        '<table class="p-grid"><tr><th>الأسبوع الدراسي</th><th>اليوم</th><th>التاريخ الهجري</th><th>وقت الحصة</th></tr>' +
        '<tr><td>'+esc(d.week||'—')+'</td><td>'+esc(d.day||'—')+'</td><td>'+esc(d.date?d.date+' هـ':'—')+'</td><td>'+((d.from&&d.to)?esc(d.from+' — '+d.to):'—')+'</td></tr></table>' +
        (d.lesson ? '<p class="p-lesson">'+esc(d.lesson)+'</p>' : '') +
        '<div class="p-heading" style="background:var(--main);">إحصائية الحضور</div>' +
        '<table class="p-stat"><tr><th>البيان</th><th>العدد</th></tr>' +
        '<tr><td>عدد الطالبات الكلي</td><td>'+d.total+'</td></tr>' +
        '<tr><td>عدد الحاضرات الفعلي</td><td>'+d.present+'</td></tr>' +
        '<tr><td>نسبة الحضور</td><td>'+pct+'٪</td></tr></table>' +
        '<table class="p-twocol"><tr>' +
          '<td class="tc-right">'+namesHtml+'</td>' +
          '<td class="tc-left"><img src="'+pieUrl+'" style="width:190px;"></td>' +
        '</tr></table>' +
        shawahedBlock +
        '<table class="p-sign"><tr>' +
          '<td class="sign-right">مديرة المدرسة: '+esc(d.principal)+'</td>' +
          '<td class="sign-left">المعلمة: '+esc(d.teacher)+'</td>' +
        '</tr></table>' +
      '</div></div>'
    );
  }

  // Inline CSS variables for the chosen design (colors + margins in mm, matching the Word page margins).
  function designVars(D){
    var mm = function(tw){ return (tw/56.6929).toFixed(2)+'mm'; };
    return '--main:#'+D.main+';--deep:#'+D.deep+';--names:#'+D.names+';--evid:#'+D.evid+';--tint:#'+D.tint+
      ';--stat-bg:#'+D.statFill+';--stat-fg:#'+D.statColor+';--lesson:#'+D.lesson+
      ';--lesson-size:'+(D.lessonSize/2)+'pt;--title-size:'+(D.titleSize/2)+'pt;--lh-size:'+(D.lhSize/2)+'pt'+
      ';--mt:'+mm(D.margins.top)+';--mb:'+mm(D.margins.bottom)+';--ml:'+mm(D.margins.left)+';--mr:'+mm(D.margins.right)+';';
  }

  var PRINT_STYLE = '<style>' +
    '#printArea *{-webkit-print-color-adjust:exact!important;print-color-adjust:exact!important;color-adjust:exact!important;}' +
    '#printArea{font-family:"Tajawal",Arial,sans-serif;direction:rtl;color:#20242B;font-size:8pt;}' +
    '.print-session{width:210mm;height:296mm;box-sizing:border-box;overflow:hidden;margin:0 auto;padding:var(--mt) var(--mr) var(--mb) var(--ml);background:#fff;}' +
    '.ps-in{width:100%;}' +
    '.p-letterhead{width:100%;border-collapse:collapse;margin-bottom:6px;}' +
    '.p-letterhead td{border:none;padding:0;vertical-align:middle;}' +
    '.lh-text{text-align:right;font-size:var(--lh-size);font-weight:bold;line-height:1.5;}' +
    '.lh-logo{text-align:left;width:70px;}' +
    '.p-title{text-align:center;color:var(--deep);font-size:var(--title-size);font-weight:bold;margin:6px 0;}' +
    '.p-grid{width:100%;border-collapse:collapse;text-align:center;margin-bottom:4px;font-size:8pt;border:1px solid #C2C1C1;}' +
    '.p-grid th{background:var(--main);color:#fff;padding:4px;border:1px solid #C2C1C1;font-weight:bold;}' +
    '.p-grid td{background:var(--tint);padding:4px;border:1px solid #C2C1C1;}' +
    '.p-lesson{text-align:center;color:var(--lesson);font-weight:bold;font-size:var(--lesson-size);margin:6px 0;}' +
    '.p-heading{color:#fff;text-align:center;padding:4px;font-weight:bold;font-size:8pt;margin:6px 0 0;break-inside:avoid;}' +
    '.p-stat{width:100%;border-collapse:collapse;text-align:center;font-size:8pt;margin-bottom:4px;break-inside:avoid;border:1px solid #C2C1C1;}' +
    '.p-stat th{background:var(--stat-bg);color:var(--stat-fg);padding:4px;border:1px solid #C2C1C1;font-weight:bold;}' +
    '.p-stat tr:nth-child(odd) td{background:var(--tint);} .p-stat td{padding:4px;border:1px solid #C2C1C1;}' +
    '.p-twocol{width:100%;border-collapse:collapse;margin-bottom:4px;break-inside:avoid;}' +
    '.p-twocol td{border:none;padding:0;vertical-align:top;}' +
    '.tc-right{width:56%;padding-left:6px!important;}' +
    '.tc-left{width:44%;text-align:center;vertical-align:middle!important;}' +
    '.names-tbl{border-collapse:collapse;font-size:8pt;width:100%;border:1px solid #C2C1C1;}' +
    '.names-tbl th{background:var(--names);color:#fff;padding:4px;font-weight:bold;border:1px solid #C2C1C1;}' +
    '.names-tbl td{padding:4px;border:1px solid #C2C1C1;}' +
    '.names-tbl tr:nth-child(even) td{background:var(--tint);}' +
    '.names-tbl{flex:1;}' +
    '.names-tbl .pnum{width:22%;text-align:center;}' +
    '.p-note{font-size:8pt;margin:4px 0;break-inside:avoid;}' +
    '.names-cols{display:flex;gap:4px;}' +
    '.p-sign{width:100%;border-collapse:collapse;margin-top:10px;}' +
    '.p-sign td{border:none;padding:0;font-size:8pt;font-weight:bold;}' +
    '.sign-right{text-align:right;} .sign-left{text-align:left;}' +
    '</style>';


  document.getElementById('genPdfBtn').addEventListener('click', async function(){
    var shared = collectShared();
    var sessions = sessionEls.map(function(el){ return collectSession(el, shared); });
    if(!validateAll(sessions)) return;

    var btn = document.getElementById('genPdfBtn');
    btn.disabled = true; btn.textContent = 'جارٍ التجهيز…';
    try{
      var D = applyDesign(selectedDesignKey());
      var logoDataUrl = 'data:image/png;base64,' + LOGO_B64;
      var htmlParts = [];
      for(var i=0;i<sessions.length;i++){
        htmlParts.push(await buildSessionHtml(sessions[i], logoDataUrl));
      }
      var pa = document.getElementById('printArea');
      pa.setAttribute('style', designVars(D));
      pa.innerHTML = PRINT_STYLE + htmlParts.join('');

      // Measure off-screen and shrink any session that would overflow one A4 page, so no extra pages appear.
      pa.style.display = 'block'; pa.style.position = 'absolute'; pa.style.left = '-99999px'; pa.style.top = '0';
      if(document.fonts && document.fonts.ready){ try{ await document.fonts.ready; }catch(e){} }
      Array.prototype.forEach.call(pa.querySelectorAll('.print-session'), function(ses){
        var inner = ses.querySelector('.ps-in');
        var cs = getComputedStyle(ses);
        var avail = ses.clientHeight - parseFloat(cs.paddingTop) - parseFloat(cs.paddingBottom);
        var z = 1, guard = 0, h = inner.getBoundingClientRect().height;
        while(h > avail && z > 0.4 && guard++ < 12){
          z = Math.max(0.4, z * Math.min(0.98, avail / h));
          inner.style.zoom = z;
          h = inner.getBoundingClientRect().height;
        }
      });
      pa.style.display = ''; pa.style.position = ''; pa.style.left = ''; pa.style.top = '';

      var missingQr = sessions.some(function(s){ return s.link && !s.qrOk; });
      if(missingQr) showToast('تعذّر إنشاء الباركود لرابط الشواهد — تأكدي من صحة الرابط', 6000);
      var originalTitle = document.title;
      document.title = ' ';
      var restoreTitle = function(){ document.title = originalTitle; window.removeEventListener('afterprint', restoreTitle); };
      window.addEventListener('afterprint', restoreTitle);

      setTimeout(function(){
        window.print();
        setTimeout(restoreTitle, 800);
        // الأرشفة/الإرسال للشيت بعد نافذة الطباعة حتى لا تتعارض معها على الجوال.
        setTimeout(function(){ archiveSessions(sessions).catch(function(e){ console.warn(e); }); }, 1500);
      }, 200);
    }catch(err){
      console.error(err);
      showToast('حدث خطأ أثناء تجهيز PDF' + errDetail(err), 15000);
    }finally{
      btn.disabled = false; btn.textContent = 'ب) ملف PDF لكل الحصص';
    }
  });

  // ============================================================
  // Draft autosave — البيانات تبقى محفوظة على الجهاز حتى لو أُعيد تحميل الصفحة (يحدث كثيرًا على الجوال)
  // ============================================================
  var DRAFT_KEY = 'report21-draft-v1';
  var SHARED_IDS = ['f_teacher','f_week','f_day','f_date','f_school','f_principal'];

  function saveDraft(){
    try{
      var shared = {};
      SHARED_IDS.forEach(function(id){ shared[id] = document.getElementById(id).value; });
      var sessions = sessionEls.map(function(el){
        var periods = Array.prototype.slice.call(el.querySelectorAll('.period-chip.active')).map(function(c){ return parseInt(c.dataset.p,10); });
        return {
          subject: el.querySelector('.f_subject').value, stage: el.querySelector('.f_stage').value,
          klass: el.querySelector('.f_class').value, total: el.querySelector('.f_total').value,
          present: el.querySelector('.f_present').value, lesson: el.querySelector('.f_lesson').value,
          notes: el.querySelector('.f_notes').value, link: el.querySelector('.f_link').value,
          names: el.querySelector('.f_names').value, periods: periods,
        };
      });
      localStorage.setItem(DRAFT_KEY, JSON.stringify({ shared: shared, sessions: sessions }));
    }catch(e){}
  }

  function restoreDraft(){
    try{
      var raw = localStorage.getItem(DRAFT_KEY);
      if(!raw) return;
      var d = JSON.parse(raw);
      if(!d || !d.sessions || !d.sessions.length) return;
      Object.keys(d.shared || {}).forEach(function(id){
        var f = document.getElementById(id);
        if(f && d.shared[id]) f.value = d.shared[id];
      });
      // Replace the initial empty card only if the user hasn't typed anything yet.
      if(sessionEls.length === 1 && isSessionEmpty(sessionEls[0])){
        sessionsWrap.removeChild(sessionEls[0]);
        sessionEls = [];
      }
      d.sessions.forEach(function(s){ addSession(s); });
    }catch(e){ console.warn('draft restore failed', e); }
  }

  restoreDraft();
  var draftTimer = null;
  function scheduleDraftSave(){ clearTimeout(draftTimer); draftTimer = setTimeout(saveDraft, 400); }
  document.addEventListener('input', scheduleDraftSave);
  document.addEventListener('change', scheduleDraftSave);
  document.addEventListener('click', scheduleDraftSave);
  document.addEventListener('visibilitychange', function(){ if(document.visibilityState === 'hidden') saveDraft(); });
  window.addEventListener('pagehide', saveDraft);
  setInterval(saveDraft, 3000);


})();
